const DoneRecordSaveRetainMessages = "DoneRecord: retention requires a region round trip through the VARIABLE form"
const DoneRecordLoadRetainMessages = "DoneRecord: retention requires a region round trip through the VARIABLE form"
const DoneRecordLoadRetain = "DoneRecord: retention requires a variable root and its region directory"
