const DoneRecordSaveRetain = "DoneRecord: retention requires a variable root and its region directory"

// ---- THE FIXED FORM, form byte 3 (mas-bandwidth/schema docs/SPEC-TABLES.md §3.4) ----
//
// A record is an eight-byte hash of the writer's layout and then the values
// in declared order, every field at its declared storage width. The writer is
// constant-offset stores; the reader is ONE loop over ONE plan.

func CompletionFixedLeaves(out []TableFixedEntry, links [][]TableFixedGuardLink, src, dst uint32) int {
	n := 0
	out[n] = TableFixedEntry{Src: src + 0, Dst: dst + uint32(unsafe.Offsetof(Completion{}.KindLength)), Size: 16, Aux: dst + uint32(unsafe.Offsetof(Completion{}.Kind)), Guard: tableFixedNoGuard, Op: tableFixedText, Meta: 1} // kind
	n++
	out[n] = TableFixedEntry{Src: src + 20, Dst: dst + uint32(unsafe.Offsetof(Completion{}.CardLength)), Size: 515, Aux: dst + uint32(unsafe.Offsetof(Completion{}.Card)), Guard: tableFixedNoGuard, Op: tableFixedText, Meta: 1} // card
	n++
	out[n] = TableFixedEntry{Src: src + 539, Dst: dst + uint32(unsafe.Offsetof(Completion{}.RowLength)), Size: 135, Aux: dst + uint32(unsafe.Offsetof(Completion{}.Row)), Guard: tableFixedNoGuard, Op: tableFixedText, Meta: 1} // row
	n++
	{
		es := src + 678
		ed := dst + uint32(unsafe.Offsetof(Completion{}.At))
		out[n] = TableFixedEntry{Src: es, Dst: ed, Size: 8, Guard: tableFixedNoGuard, Op: tableFixedCopy}
		n++
	}
	return n
}

func CompletionFixedWriteBody(b []byte, value *Completion) {
	tableFixedPut32(b[0:], uint32(value.KindLength))
	copy(b[0:][4:], value.Kind[:min(uint32(value.KindLength), 16)])
	tableFixedPut32(b[20:], uint32(value.CardLength))
	copy(b[20:][4:], value.Card[:min(uint32(value.CardLength), 515)])
	tableFixedPut32(b[539:], uint32(value.RowLength))
	copy(b[539:][4:], value.Row[:min(uint32(value.RowLength), 135)])
	tableFixedPut64(b[678:], uint64(value.At))
}

func DoneRecordFixedLeaves(out []TableFixedEntry, links [][]TableFixedGuardLink, src, dst uint32) int {
	n := 0
	{
		es := src + 0
		ed := dst + uint32(unsafe.Offsetof(DoneRecord{}.Epoch))
		out[n] = TableFixedEntry{Src: es, Dst: ed, Size: 8, Guard: tableFixedNoGuard, Op: tableFixedCopy}
		n++
	}
	out[n] = TableFixedEntry{Src: src + 8, Dst: dst + uint32(unsafe.Offsetof(DoneRecord{}.CursorLength)), Size: 41, Aux: dst + uint32(unsafe.Offsetof(DoneRecord{}.Cursor)), Guard: tableFixedNoGuard, Op: tableFixedText, Meta: 1} // cursor
	n++
	out[n] = TableFixedEntry{Src: src + 53, Dst: dst + uint32(unsafe.Offsetof(DoneRecord{}.DoneCount)), Size: 95, Guard: tableFixedNoGuard, Op: tableFixedCount} // done count
	n++
	for i := uint32(0); i < 95; i++ {
		es := src + 57 + i*686
		ed := dst + uint32(unsafe.Offsetof(DoneRecord{}.Done)) + i*uint32(unsafe.Sizeof(Completion{}))
		n += CompletionFixedLeaves(out[n:], links[n:], es, ed)
	}
	{
		es := src + 65227
		ed := dst + uint32(unsafe.Offsetof(DoneRecord{}.Pages))
		out[n] = TableFixedEntry{Src: es, Dst: ed, Size: 4, Guard: tableFixedNoGuard, Op: tableFixedCopy}
		n++
	}
	return n
}

func DoneRecordFixedWriteBody(b []byte, value *DoneRecord) {
	tableFixedPut64(b[0:], uint64(value.Epoch))
	tableFixedPut32(b[8:], uint32(value.CursorLength))
	copy(b[8:][4:], value.Cursor[:min(uint32(value.CursorLength), 41)])
	tableFixedPut32(b[53:], uint32(value.DoneCount))
	{
		livei := min(max(int64(value.DoneCount), 0), 95)
		for i := int64(0); i < livei; i++ {
			clear(b[57:][i*686 : i*686+686])
			CompletionFixedWriteBody(b[57:][i*686:], &value.Done[i])
		}
		clear(b[57:][livei*686 : 65170])
	}
	tableFixedPut32(b[65227:], uint32(value.Pages))
}

// Completion's read-side bounds.
func CompletionFixedClampBody(value *Completion, clamped *int32) {
	_, _ = value, clamped
}

// DoneRecord's read-side bounds.
func DoneRecordFixedClampBody(value *DoneRecord, clamped *int32) {
	_, _ = value, clamped
	for i := int64(0); i < int64(value.DoneCount); i++ {
		CompletionFixedClampBody(&value.Done[i], clamped)
	}
}

// Completion's write-side contract (mas-bandwidth/schema docs/FIXED-FORM-ALGORITHM.md §3.1): false is TableRefuseInvalidValue.
func CompletionFixedCheckBody(value *Completion) bool {
	var z, hi uint64
	if n := int(value.KindLength); uint(n) > 16 {
		return false
	} else {
		p := value.Kind[:n]
		for len(p) >= 16 {
			x, y := tableFixedGet64(p), tableFixedGet64(p[8:])
			hi |= x | y
			z |= (x-0x0101010101010101)&^x | (y-0x0101010101010101)&^y
			p = p[16:]
		}
		if len(p) >= 8 {
			x := tableFixedGet64(p)
			hi |= x
			z |= (x - 0x0101010101010101) &^ x
			p = p[8:]
		}
		if len(p) > 0 {
			var x uint64
			if n >= 8 {
				x = tableFixedGet64(value.Kind[n-8:])
			} else {
				m := uint64(1)<<(8*uint(n)) - 1
				x = tableFixedGet64(value.Kind[:])&m | 0x0101010101010101&^m
			}
			hi |= x
			z |= (x - 0x0101010101010101) &^ x
		}
	}
	if n := int(value.CardLength); uint(n) > 515 {
		return false
	} else {
		p := value.Card[:n]
		for len(p) >= 16 {
			x, y := tableFixedGet64(p), tableFixedGet64(p[8:])
			hi |= x | y
			z |= (x-0x0101010101010101)&^x | (y-0x0101010101010101)&^y
			p = p[16:]
		}
		if len(p) >= 8 {
			x := tableFixedGet64(p)
			hi |= x
			z |= (x - 0x0101010101010101) &^ x
			p = p[8:]
		}
		if len(p) > 0 {
			var x uint64
			if n >= 8 {
				x = tableFixedGet64(value.Card[n-8:])
			} else {
				m := uint64(1)<<(8*uint(n)) - 1
				x = tableFixedGet64(value.Card[:])&m | 0x0101010101010101&^m
			}
			hi |= x
			z |= (x - 0x0101010101010101) &^ x
		}
	}
	if n := int(value.RowLength); uint(n) > 135 {
		return false
	} else {
		p := value.Row[:n]
		for len(p) >= 16 {
			x, y := tableFixedGet64(p), tableFixedGet64(p[8:])
			hi |= x | y
			z |= (x-0x0101010101010101)&^x | (y-0x0101010101010101)&^y
			p = p[16:]
		}
		if len(p) >= 8 {
			x := tableFixedGet64(p)
			hi |= x
			z |= (x - 0x0101010101010101) &^ x
			p = p[8:]
		}
		if len(p) > 0 {
			var x uint64
			if n >= 8 {
				x = tableFixedGet64(value.Row[n-8:])
			} else {
				m := uint64(1)<<(8*uint(n)) - 1
				x = tableFixedGet64(value.Row[:])&m | 0x0101010101010101&^m
			}
			hi |= x
			z |= (x - 0x0101010101010101) &^ x
		}
	}
	if z&0x8080808080808080 != 0 {
		return false
	}
	if hi&0x8080808080808080 != 0 {
		return CompletionFixedCheckBodyExact(value)
	}
	return true
}

// CompletionFixedCheckBodyExact is CompletionFixedCheckBody with each string asked by
// tableFixedUtf8Ok: the answer for text with a byte at or past 0x80 (§3.1).
func CompletionFixedCheckBodyExact(value *Completion) bool {
	_ = value
	if uint32(value.KindLength) > 16 || !tableFixedUtf8Ok(value.Kind[:value.KindLength]) {
		return false
	}
	if uint32(value.CardLength) > 515 || !tableFixedUtf8Ok(value.Card[:value.CardLength]) {
		return false
	}
	if uint32(value.RowLength) > 135 || !tableFixedUtf8Ok(value.Row[:value.RowLength]) {
		return false
	}
	return true
}

// DoneRecord's write-side contract (mas-bandwidth/schema docs/FIXED-FORM-ALGORITHM.md §3.1): false is TableRefuseInvalidValue.
func DoneRecordFixedCheckBody(value *DoneRecord) bool {
	var z, hi uint64
	if n := int(value.CursorLength); uint(n) > 41 {
		return false
	} else {
		p := value.Cursor[:n]
		for len(p) >= 16 {
			x, y := tableFixedGet64(p), tableFixedGet64(p[8:])
			hi |= x | y
			z |= (x-0x0101010101010101)&^x | (y-0x0101010101010101)&^y
			p = p[16:]
		}
		if len(p) >= 8 {
			x := tableFixedGet64(p)
			hi |= x
			z |= (x - 0x0101010101010101) &^ x
			p = p[8:]
		}
		if len(p) > 0 {
			var x uint64
			if n >= 8 {
				x = tableFixedGet64(value.Cursor[n-8:])
			} else {
				m := uint64(1)<<(8*uint(n)) - 1
				x = tableFixedGet64(value.Cursor[:])&m | 0x0101010101010101&^m
			}
			hi |= x
			z |= (x - 0x0101010101010101) &^ x
		}
	}
	if value.DoneCount < 0 || value.DoneCount > 95 {
		return false
	}
	for i := int64(value.DoneCount) - 1; i >= 0; i-- {
		if !CompletionFixedCheckBody(&value.Done[i]) {
			return false
		}
	}
	if z&0x8080808080808080 != 0 {
		return false
	}
	if hi&0x8080808080808080 != 0 {
		return DoneRecordFixedCheckBodyExact(value)
	}
	return true
}

// DoneRecordFixedCheckBodyExact is DoneRecordFixedCheckBody with each string asked by
// tableFixedUtf8Ok: the answer for text with a byte at or past 0x80 (§3.1).
func DoneRecordFixedCheckBodyExact(value *DoneRecord) bool {
	_ = value
	if uint32(value.CursorLength) > 41 || !tableFixedUtf8Ok(value.Cursor[:value.CursorLength]) {
		return false
	}
	if value.DoneCount < 0 || value.DoneCount > 95 {
		return false
	}
	for i := int64(value.DoneCount) - 1; i >= 0; i-- {
		if !CompletionFixedCheckBody(&value.Done[i]) {
			return false
		}
	}
	return true
}

// THE READ-SIDE BOUNDS (mas-bandwidth/schema docs/SPEC-TABLES.md §3.4): a ranged scalar's
// declared min and max, and an ORDINAL's set — a union tag past the arm
// count, an enum ordinal past the enum's top value. Straight-line, after
// the copy, over STORAGE, so the identity plan and a plan compiled from a
// stranger's layout are held to the same numbers by the same pass. Every
// clamp COUNTS. The pass walks LIVE elements only: a counted array's live
// count, not its slack; an optional's payload only when present; a union's
// set arm, not the others.
func CompletionFixedClamp(value *Completion, report *TableReport) {
	clamped := int32(0)
	CompletionFixedClampBody(value, &clamped)
	report.Clamped += clamped
}

